script:
'use strict';
const API = 'https://picaapi.picacomic.com';
function fail(message) { throw new Error(message); }
function positive(value) { return Number.isInteger(value) && value > 0; }
function pageNumber(page) {
  if (!positive(page)) fail('Invalid page number');
  return page;
}
async function api(path, body) {
  const response = await triomi.fetch(API + path, body === undefined ? {} : {
    method: 'POST', body: JSON.stringify(body), bodyType: 'json'
  });
  if (response.status !== 200) fail('Pica API HTTP ' + response.status);
  let value;
  try { value = JSON.parse(response.body); } catch (_) { fail('Invalid Pica JSON'); }
  if (!value || value.code !== 200 || !value.data) fail('Invalid Pica API data');
  return value.data;
}
function image(media) {
  if (!media || typeof media.fileServer !== 'string' ||
      !/^https:\/\/[^\s/?#@]+(?:\/[^\s?#]*)?$/.test(media.fileServer) ||
      typeof media.path !== 'string' || !media.path ||
      /(^|\/)\.\.(\/|$)/.test(media.path)) fail('Invalid Pica image');
  return media.fileServer.replace(/\/+$/, '') + '/static/' + media.path.replace(/^\/+/, '');
}
function idOf(url, snapshot) {
  const candidate = snapshot && snapshot.remoteId;
  if (typeof candidate === 'string' && /^[a-zA-Z0-9_-]+$/.test(candidate)) return candidate;
  const match = /^https:\/\/picaapi\.picacomic\.com\/comics\/([a-zA-Z0-9_-]+)$/.exec(url);
  if (!match) fail('Invalid Pica comic identity');
  return match[1];
}
function item(comic) {
  if (!comic || typeof comic._id !== 'string' || !/^[a-zA-Z0-9_-]+$/.test(comic._id) ||
      typeof comic.title !== 'string' || !comic.title.trim()) fail('Invalid Pica comic');
  const tags = Array.isArray(comic.tags) ? comic.tags : (comic.categories || []);
  return {remoteId: comic._id, type: 'manga', title: comic.title,
    url: API + '/comics/' + comic._id, coverUrl: image(comic.thumb),
    author: [comic.author, comic.artist].filter(Boolean).filter((x, i, a) => a.indexOf(x) === i).join(' / '),
    description: comic.description || '', tags: Array.from(new Set(tags.map(x => String(x).trim()).filter(Boolean))),
    status: comic.finished ? '已完结' : '连载中'};
}
function list(comics, options) {
  if (!Array.isArray(comics)) fail('Invalid Pica comic list');
  const blocked = options && Array.isArray(options.blocked) ? options.blocked : [];
  return comics.filter(c => {
    const genres = Array.isArray(c.tags) ? c.tags : (c.categories || []);
    return !genres.some(g => blocked.indexOf(String(g).trim()) >= 0);
  }).map(item);
}
function slice(value, expectedPage) {
  if (!value || !Array.isArray(value.docs) || !Number.isInteger(value.pages) ||
      value.pages < 0 || value.pages > 200 || value.page !== expectedPage ||
      (value.pages > 0 && expectedPage > value.pages && value.docs.length > 0)) {
    fail('Invalid or excessive Pica pagination');
  }
  return value;
}
async function allPages(path, field) {
  const first = slice((await api(path + '?page=1'))[field], 1);
  const result = first.docs.slice();
  for (let p = 2; p <= first.pages; p++) {
    const next = slice((await api(path + '?page=' + p))[field], p);
    if (next.pages !== first.pages) fail('Pica pagination changed; reload chapter');
    result.push(...next.docs);
    if (result.length > 20000) fail('Pica response exceeds safety limit');
  }
  return result;
}
function sort(options) { return options && ['dd', 'da', 'ld', 'vd'].indexOf(options.sort) >= 0 ? options.sort : 'dd'; }
async function discover(url, page, options) {
  pageNumber(page);
  if (url.indexOf(API + '/comics/leaderboard?') === 0) {
    if (page !== 1) return [];
    return list((await api(url.substring(API.length))).comics, options);
  }
  if (url === API + '/comics/random') return list((await api('/comics/random')).comics, options);
  const path = url === API + '/users/favourite' ? '/users/favourite' : '/comics';
  const response = await api(path + '?page=' + page + '&s=' + sort(options));
  return list(slice(response.comics, page).docs, options);
}
async function search(keyword, page, options) {
  return searchTagged(keyword, page, [], options);
}
async function searchTags() {
  const categories = (await api('/categories')).categories;
  if (!Array.isArray(categories)) fail('Invalid Pica categories');
  return categories.filter(c => c && typeof c.title === 'string' && c.title.trim())
    .map(c => ({id: c.title, label: c.title}));
}
async function searchTagged(keyword, page, tags, options) {
  pageNumber(page);
  const categories = Array.isArray(tags) ? tags.filter(t => typeof t === 'string' && t.trim()) : [];
  const text = String(keyword || '').trim();
  let data;
  if (!text && categories.length <= 1) {
    data = await api('/comics?page=' + page + '&s=' + sort(options) +
      (categories.length ? '&c=' + encodeURIComponent(categories[0]) : ''));
  } else {
    const payload = {keyword: text, sort: sort(options)};
    if (categories.length) payload.categories = categories;
    data = await api('/comics/advanced-search?page=' + page, payload);
  }
  return list(slice(data.comics, page).docs, options);
}
async function detail(url, snapshot) {
  const id = idOf(url, snapshot);
  const comic = item((await api('/comics/' + id)).comic);
  const eps = await allPages('/comics/' + id + '/eps', 'eps');
  const seen = new Set();
  const chapters = eps.map(ep => {
    if (!ep || !positive(ep.order) || typeof ep.title !== 'string' || seen.has(ep.order)) {
      fail('Invalid or duplicate Pica episode');
    }
    seen.add(ep.order);
    return {remoteId: id + '/order/' + ep.order, title: ep.title,
      url: API + '/comics/' + id + '/order/' + ep.order, number: ep.order,
      sortIndex: ep.order, releaseDate: ep.updated_at || null};
  }).sort((a, b) => a.number - b.number);
  if (!chapters.length) fail('Pica returned no readable episodes');
  return {item: comic, chapters: chapters};
}
async function content(url) {
  const match = /^https:\/\/picaapi\.picacomic\.com\/comics\/[a-zA-Z0-9_-]+\/order\/[1-9][0-9]*$/.exec(url);
  if (!match) fail('Invalid Pica chapter identity');
  const pages = await allPages(url.substring(API.length) + '/pages', 'pages');
  if (!pages.length) fail('Pica returned no readable pages');
  return {images: pages.map(p => image(p.media)), imageHeaders: {'User-Agent': 'okhttp/3.8.1'}};
}
